package store

import (
	"context"
	"database/sql"
	"errors"
	"testing"
)

// TestStore_ItemParsers covers the item_parsers attachment control table
// (parser-display D-3). Table-driven across the set/list round-trip (ordered
// positions), full-replacement (stale rows removed, empty clears), the
// unknown-item guard (wrapped sql.ErrNoRows — the api 404), re-scan survival
// (PutItem upsert preserves the item id → attachments persist), sibling
// isolation (rows are keyed by item; nothing propagates), and the
// orphan-tolerant read (attachments die with the item's rows on
// re-identify cleanup).
func TestStore_ItemParsers(t *testing.T) {
	ctx := context.Background()

	putItem := func(t *testing.T, s *Store, id, fileID string) {
		t.Helper()
		it := Item{
			ID: id, ModuleID: "tv", LibraryID: 7, FileID: fileID,
			RelativePath:  "dir/" + fileID + ".mkv",
			MediaType:     "video",
			Document:      []byte(`{"parsed":{}}`),
			SchemaVersion: 1,
		}
		if err := s.PutItem(ctx, it); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}

	t.Run("set_list_roundtrip_ordered", func(t *testing.T) {
		s := openStore(t)
		putItem(t, s, "itm_7_a", "fa")
		want := []string{"anitomy", "tmdb"}
		if err := s.SetItemParsers(ctx, "itm_7_a", want); err != nil {
			t.Fatalf("SetItemParsers: %v", err)
		}
		got, err := s.ListItemParsers(ctx, "itm_7_a")
		if err != nil {
			t.Fatalf("ListItemParsers: %v", err)
		}
		if len(got) != len(want) || got[0] != want[0] || got[1] != want[1] {
			t.Fatalf("ListItemParsers = %v, want %v (attachment order preserved)", got, want)
		}
	})

	t.Run("replace_is_full_replacement", func(t *testing.T) {
		s := openStore(t)
		putItem(t, s, "itm_7_b", "fb")
		if err := s.SetItemParsers(ctx, "itm_7_b", []string{"anitomy", "tmdb"}); err != nil {
			t.Fatalf("SetItemParsers #1: %v", err)
		}
		// Reordering through a subset must not resurrect dropped ids.
		if err := s.SetItemParsers(ctx, "itm_7_b", []string{"tmdb", "anitomy"}); err != nil {
			t.Fatalf("SetItemParsers #2: %v", err)
		}
		got, err := s.ListItemParsers(ctx, "itm_7_b")
		if err != nil {
			t.Fatalf("ListItemParsers: %v", err)
		}
		if len(got) != 2 || got[0] != "tmdb" || got[1] != "anitomy" {
			t.Fatalf("ListItemParsers = %v, want [tmdb anitomy] (reordered)", got)
		}
		if err := s.SetItemParsers(ctx, "itm_7_b", nil); err != nil {
			t.Fatalf("SetItemParsers clear: %v", err)
		}
		if got, err := s.ListItemParsers(ctx, "itm_7_b"); err != nil || len(got) != 0 {
			t.Fatalf("after clear: ListItemParsers = %v, err = %v, want empty", got, err)
		}
	})

	t.Run("unknown_item_writes_nothing", func(t *testing.T) {
		s := openStore(t)
		err := s.SetItemParsers(ctx, "itm_missing", []string{"anitomy"})
		if !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("SetItemParsers on missing item = %v, want wrapped sql.ErrNoRows (api 404)", err)
		}
	})

	t.Run("rescan_upsert_preserves_attachments", func(t *testing.T) {
		s := openStore(t)
		putItem(t, s, "itm_7_c", "fc")
		if err := s.SetItemParsers(ctx, "itm_7_c", []string{"anitomy"}); err != nil {
			t.Fatalf("SetItemParsers: %v", err)
		}
		// The scan-path re-scan: PutItem upserts by file_id, PRESERVING the
		// row's id — the attachment is keyed to the id, so it must survive
		// with a refreshed document untouched by the attachment write.
		putItem(t, s, "itm_7_c", "fc")
		got, err := s.ListItemParsers(ctx, "itm_7_c")
		if err != nil {
			t.Fatalf("ListItemParsers after re-scan: %v", err)
		}
		if len(got) != 1 || got[0] != "anitomy" {
			t.Fatalf("after re-scan: ListItemParsers = %v, want [anitomy] (survival)", got)
		}
	})

	t.Run("sibling_isolation", func(t *testing.T) {
		s := openStore(t)
		putItem(t, s, "itm_7_d", "fd")
		putItem(t, s, "itm_7_e", "fe")
		if err := s.SetItemParsers(ctx, "itm_7_d", []string{"anitomy"}); err != nil {
			t.Fatalf("SetItemParsers: %v", err)
		}
		got, err := s.ListItemParsers(ctx, "itm_7_e")
		if err != nil {
			t.Fatalf("ListItemParsers sibling: %v", err)
		}
		if len(got) != 0 {
			t.Fatalf("sibling ListItemParsers = %v, want empty (nothing propagates)", got)
		}
	})

	t.Run("reidentify_removes_attachments_with_item_rows", func(t *testing.T) {
		s := openStore(t)
		putItem(t, s, "itm_7_old", "f_old")
		if err := s.SetItemParsers(ctx, "itm_7_old", []string{"anitomy"}); err != nil {
			t.Fatalf("SetItemParsers: %v", err)
		}
		// Root-move re-identify: the scanner mints a NEW file_id → a NEW item
		// identity. The new item starts with NO attachments (identity-keyed,
		// nothing copied across identities).
		putItem(t, s, "itm_7_new", "f_new")
		got, err := s.ListItemParsers(ctx, "itm_7_new")
		if err != nil {
			t.Fatalf("ListItemParsers re-identified: %v", err)
		}
		if len(got) != 0 {
			t.Fatalf("re-identified item = %v, want empty (attachments die with identity)", got)
		}
		// When the re-identify cleanup removes the old item rows, the old
		// attachments go with them: the read is orphan-tolerant (join to
		// items), never surfacing rows whose item is gone.
		if _, err := s.db.ExecContext(ctx, "DELETE FROM items WHERE id = ?", "itm_7_old"); err != nil {
			t.Fatalf("remove old item row: %v", err)
		}
		got, err = s.ListItemParsers(ctx, "itm_7_old")
		if err != nil {
			t.Fatalf("ListItemParsers removed item: %v", err)
		}
		if len(got) != 0 {
			t.Fatalf("removed item = %v, want empty (orphan-tolerant read)", got)
		}
	})
}
